#!/usr/bin/env python3
"""Original fixture -> real DuckDB2 agent-mode comparisons -> complete follow-up file."""
from pathlib import Path
from datetime import datetime,timezone
import csv,hashlib,html,json,subprocess,time,zipfile

BASE=Path(__file__).resolve().parent
INP=BASE/'input';OUT=BASE/'output';LOG=BASE/'runlogs';SQL=BASE/'sql'
def save(p,obj):p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def run(label,flags,query):
 cmd=['./bin/duckdb','-no-init',*flags,':memory:','-c',query]
 start=datetime.now(timezone.utc).isoformat();t=time.perf_counter()
 r=subprocess.run(cmd,cwd=BASE,text=True,capture_output=True,timeout=15)
 (LOG/(label+'.stdout.txt')).write_text(r.stdout);(LOG/(label+'.stderr.txt')).write_text(r.stderr)
 rec={'label':label,'argv':cmd,'started_at_utc':start,'seconds':round(time.perf_counter()-t,6),'exit_code':r.returncode,'stdout_bytes':len(r.stdout.encode()),'stderr_bytes':len(r.stderr.encode())}
 save(LOG/(label+'.command.json'),rec);return r,rec
def main():
 for p in [INP,OUT,LOG,SQL]:p.mkdir(exist_ok=True)
 started=datetime.now(timezone.utc).isoformat();records=[]
 for i in range(1,1201):
  delivered=i%5!=0
  records.append({'parcel_id':f'P{i:04}','route':f'R{(i-1)%4+1}','promised_days':3,'status':'delivered' if delivered else 'in_transit','actual_days':2+i%4 if delivered else ''})
 with (INP/'parcels.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
 save(INP/'fixture-description.json',{'origin':'Original fictional teaching fixture generated by this script; not real business records, public statistics, or observed AI failure.','rows':1200,'rule':'Delivered when id not divisible by5; promised3days; delivered actual=2+(id mod4); in-transit actual is blank.','task':'Find delivered parcels whose actual days exceed promised days; export complete follow-up list. In-transit is not counted as delivered-late.','license':'CC0-1.0 for the original fixture and original report; DuckDB MIT license separate.'})
 setup="SET autoinstall_known_extensions=false; SET autoload_known_extensions=false; SET threads=1; SET memory_limit='128MB'; CREATE TABLE parcels AS SELECT * FROM read_csv('input/parcels.csv',columns={'parcel_id':'VARCHAR','route':'VARCHAR','promised_days':'INTEGER','status':'VARCHAR','actual_days':'INTEGER'},header=true);\n"
 preview=setup+'SELECT * FROM parcels ORDER BY parcel_id;'
 (SQL/'01-preview.sql').write_text(preview+'\n')
 runs=[]
 for label,flags in [('preview-human',['-no-agent']),('preview-agent',['-agent'])]:
  r,rec=run(label,flags,preview);assert r.returncode==0;runs.append(rec)
 reverse=setup+'SELECT * FROM parcels ORDER BY parcel_id DESC;'
 r,rec=run('preview-agent-reversed',['-agent'],reverse);assert r.returncode==0;runs.append(rec)
 typo=setup+'SELECT parcel_id, actual_day FROM parcels LIMIT 1;'
 (SQL/'02-intentional-typo.sql').write_text('-- Author intentionally misspelled actual_days; not claimed AI-generated error.\n'+typo+'\n')
 for label,flags in [('typo-human',['-no-agent']),('typo-agent',['-agent'])]:
  r,rec=run(label,flags,typo);assert r.returncode!=0;runs.append(rec)
 task="SELECT parcel_id,route,promised_days,actual_days,actual_days-promised_days AS days_late FROM parcels WHERE status='delivered' AND actual_days>promised_days ORDER BY parcel_id"
 export=setup+"DESCRIBE parcels; SELECT status,count(*) AS records FROM parcels GROUP BY status ORDER BY status; SELECT route,count(*) AS delivered_late FROM parcels WHERE status='delivered' AND actual_days>promised_days GROUP BY route ORDER BY route; COPY ("+task+") TO 'output/late-followup.csv' (HEADER,DELIMITER ','); COPY ("+task+") TO 'output/late-followup.parquet' (FORMAT PARQUET); SELECT count(*) AS exported_rows FROM read_csv('output/late-followup.csv');"
 (SQL/'03-followup.sql').write_text(export+'\n')
 r,rec=run('complete-export',['-agent'],export);assert r.returncode==0;runs.append(rec)
 readback="SET autoinstall_known_extensions=false; SET autoload_known_extensions=false; COPY (SELECT * FROM 'output/late-followup.parquet' ORDER BY parcel_id) TO 'output/parquet-readback.csv' (HEADER,DELIMITER ',');"
 r,rec=run('parquet-readback',['-no-agent'],readback);assert r.returncode==0;runs.append(rec)
 # Independent stdlib oracle checks the entire exported record set, not the truncated screen.
 expected=[]
 for r in records:
  if r['status']=='delivered' and int(r['actual_days'])>int(r['promised_days']):
   expected.append({k:str(v) for k,v in dict(parcel_id=r['parcel_id'],route=r['route'],promised_days=r['promised_days'],actual_days=r['actual_days'],days_late=int(r['actual_days'])-int(r['promised_days'])).items()})
 with (OUT/'late-followup.csv').open() as f:actual=list(csv.DictReader(f))
 with (OUT/'parquet-readback.csv').open() as f:back=list(csv.DictReader(f))
 assert actual==expected==back
 assert len(actual)==480 and not any(int(r['days_late'])<=0 for r in actual)
 version,rec=run('version',['-no-agent'],'SELECT version();');assert version.returncode==0;runs.append(rec)
 help_r,rec=run('agent-help',['-agent'],'.help agent');assert help_r.returncode==0;runs.append(rec)
 agent=(LOG/'preview-agent.stdout.txt').read_text();human=(LOG/'preview-human.stdout.txt').read_text()
 err=(LOG/'typo-agent.stderr.txt').read_text()
 rows=''.join('<tr>'+''.join('<td>'+html.escape(str(r[k]))+'</td>' for k in ['parcel_id','route','promised_days','actual_days','days_late'])+'</tr>' for r in actual[:8]+actual[-4:])
 page='''<!doctype html><html lang="zh-TW"><meta charset="utf-8"><title>配送追蹤清單｜本地DuckDB2實跑</title><style>body{font:20px/1.6 sans-serif;color:#172d46;background:#f8faf8;max-width:1100px;margin:40px auto;padding:0 25px}h1{font-size:38px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ccd7d9;text-align:left;padding:8px}pre{white-space:pre-wrap;font:15px/1.5 monospace;background:#e5eeee;padding:20px}a{color:#007f85}.note{border-left:5px solid #b83e2a;padding-left:15px}</style><h1>同一份配送紀錄，交出完整跟進清單</h1><p class="note">原創虛構練習資料；不是實際業務／公共統計。本次只運行DuckDB2.0 CLI，沒有呼叫AI模型或使用Claude Cowork。</p><p>輸入1,200筆：已送達960筆、在途240筆。篩出已送達且實際天數超過承諾3天的480筆。R2、R3各240筆。</p><p><a href="late-followup.csv" download>完整480筆CSV</a> · <a href="late-followup.parquet" download>同一份Parquet</a> · <a href="../sql/03-followup.sql">完整SQL</a> · <a href="../results.json">實跑紀錄</a></p><h2>這12列只是樣本</h2><p>前8列＋末4列；完整檔案有480列。畫面預覽、查詢結果及匯出檔是三個不同層次。</p><table><tr><th>parcel_id</th><th>route</th><th>promised_days</th><th>actual_days</th><th>days_late</th></tr>'''+rows+'''</table><h2>完整篩選規則</h2><pre>'''+html.escape(task)+'''</pre><h2>新版agent模式的真實輸出</h2><p>同一2.0版本的-agent／-no-agent對照；不是與1.5的版本速度比。CSV／SQL／Parquet是既有能力，agent輸出形式才是本次新特性。</p><pre>'''+html.escape(agent)+'''</pre><p class="note">輸出較精簡不等於查詢或AI回答正確；沒有量測token、成本、時間節省或模型理解效果。</p></html>'''
 (OUT/'followup-report.html').write_text(page)
 results={'status':'PASS','started_at_utc':started,'finished_at_utc':datetime.now(timezone.utc).isoformat(),'version_stdout':version.stdout.strip(),'package_sha256':hashlib.sha256((BASE/'sources/duckdb-cli-package.raw').read_bytes()).hexdigest(),'new_feature_actually_run':'DuckDB2 CLI agent mode: compact Markdown/truncation footer, result hash, JSON error versus human rendering on same2.0 binary','existing_capabilities_not_claimed_new':['CSV reading','SQL filtering/grouping','CSV/Parquet export'],'input_rows':1200,'delivered':960,'in_transit':240,'late_followup':480,'route_counts':{'R2':240,'R3':240},'whole_csv_matches_independent_stdlib_oracle':True,'parquet_roundtrip_matches_csv':True,'preview_human_stdout_bytes':len(human.encode()),'preview_agent_stdout_bytes':len(agent.encode()),'agent_error_stderr':err,'runs':runs,'not_tested':['AI model or agent reasoning','token or dollar savings','benchmark speedup','server/quack mode','migration of existing databases','long-running query cost estimation']}
 save(BASE/'results.json',results)
 print(json.dumps({k:v for k,v in results.items() if k!='runs' and k!='agent_error_stderr'},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
